WITH matched_keys AS (SELECT brand, category FROM products EXCEPT ALL SELECT brand, category FROM products WHERE brand IN ('Stark', 'Initech', 'Umbrella')), reconciled AS (SELECT s.* FROM products s JOIN matched_keys k ON s.brand = k.brand AND s.category = k.category) SELECT CASE WHEN price >= 1250 THEN 'LARGE' ELSE 'SMALL' END AS price_tier, category, COUNT(*) FILTER (WHERE brand = 'Stark') AS stark_rows, COUNT(*) AS row_count, COUNT(CASE WHEN brand = 'Initech' THEN 1 END) AS initech_count, SUM(CASE WHEN category = 'Electronics' THEN stock_qty ELSE 0 END) AS electronics_stock_qty, AVG(stock_qty) FILTER (WHERE category = 'Fashion') AS fashion_avg_stock_qty, COUNT(CASE WHEN brand = 'Globex' THEN 1 END) AS globex_count FROM reconciled GROUP BY GROUPING SETS ((CASE WHEN price >= 1250 THEN 'LARGE' ELSE 'SMALL' END, category), (CASE WHEN price >= 1250 THEN 'LARGE' ELSE 'SMALL' END)) ORDER BY electronics_stock_qty;
